import{_ as o,o as a,c as s,ae as d}from"./chunks/framework.YL6nI5ZP.js";const i="/docs/assets/simulation-pipeline.BhlzwjIc.png",h=JSON.parse('{"title":"El pipeline de simulación y el puente al motor WASM","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/02-pipeline-de-simulacion.md","filePath":"es/explanation/02-pipeline-de-simulacion.md"}'),r={name:"es/explanation/02-pipeline-de-simulacion.md"};function t(c,e,n,l,p,m){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="el-pipeline-de-simulacion-y-el-puente-al-motor-wasm" tabindex="-1">El pipeline de simulación y el puente al motor WASM <a class="header-anchor" href="#el-pipeline-de-simulacion-y-el-puente-al-motor-wasm" aria-label="Permalink to &quot;El pipeline de simulación y el puente al motor WASM&quot;">​</a></h1><p>Cómo fluye una simulación desde la UI al motor y de vuelta — los workers, los contratos de mensajes y el puente WASM que conecta JavaScript con el motor C++.</p><h2 id="flujo-de-extremo-a-extremo" tabindex="-1">Flujo de extremo a extremo <a class="header-anchor" href="#flujo-de-extremo-a-extremo" aria-label="Permalink to &quot;Flujo de extremo a extremo&quot;">​</a></h2><p>Presionar <strong>Run</strong> (<code>#btn-run</code>, <code>ui.js:216</code>) recorre este camino:</p><p><img src="'+i+'" alt="Pipeline de simulación"></p><p>Los dos backends comparten la misma superficie de corrida pero difieren en fidelidad: el motor WASM es la referencia (f64, fiel), mientras que el marcher WebGPU es una vía de rendimiento opt-in (<code>Net.useGpu2d === true</code>) que reimplementa el solver 2D explícito local-inercial en la GPU.</p><h2 id="validacion-previa-al-vuelo" tabindex="-1">Validación previa al vuelo <a class="header-anchor" href="#validacion-previa-al-vuelo" aria-label="Permalink to &quot;Validación previa al vuelo&quot;">​</a></h2><p><code>runSimulation</code> (<code>app.js:1392-1489</code>) aborta con una advertencia si: no hay nodos; no hay <code>OUTFALL</code>; o hay una malla 2D presente mientras las unidades son US (<code>app.js:1402-1406</code> — el 2D es solo SI).</p><h2 id="estimacion-de-duracion-progreso-cosmetico" tabindex="-1">Estimación de duración (progreso cosmético) <a class="header-anchor" href="#estimacion-de-duracion-progreso-cosmetico" aria-label="Permalink to &quot;Estimación de duración (progreso cosmético)&quot;">​</a></h2><p><code>estimateSimDurationMs(inpText, networkSize)</code> (<code>app.js:1083-1129</code>) parsea START/END de <code>[OPTIONS]</code> y <code>ROUTING_STEP</code> del INP y extrapola el tiempo de reloj. La barra de progreso 1D de Run Status se maneja con un <code>setInterval</code> contra esta estimación, con tope en 99% y luego asintótica a 100% (<code>app.js:1252-1271</code>).</p><h2 id="web-workers" tabindex="-1">Web Workers <a class="header-anchor" href="#web-workers" aria-label="Permalink to &quot;Web Workers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Worker</th><th>Instanciado en</th><th>Rol</th></tr></thead><tbody><tr><td><code>parseWorker.js</code></td><td><code>app.js:933</code> (por import)</td><td>Parsear el texto <code>.inp</code> fuera del hilo principal</td></tr><tr><td><code>simWorker.js</code></td><td><code>app.js:969-978</code> (<strong>persistente</strong>)</td><td>Corrida del motor 1D; pre-calentado en la carga (<code>app.js:1304</code>)</td></tr><tr><td><code>openSwmm2dWorker.js</code></td><td><code>app.js:1143</code> (por corrida 2D)</td><td>Motor acoplado 1D+2D + muestreo de cuadros (<strong>default — la referencia f64</strong>)</td></tr><tr><td><code>webgpu/gpu2dWorker.js</code></td><td><code>app.js:1186</code> (por corrida 2D, <strong>solo si <code>Net.useGpu2d === true</code></strong>)</td><td>Marcher WebGPU f32 (vía de rendimiento opt-in)</td></tr></tbody></table><p><strong>Contratos de mensajes de los workers</strong> (principal → worker):</p><ul><li><code>parseWorker</code>: <code>{ text }</code> → postea <code>{type:&#39;progress&#39;|&#39;done&#39;, model}</code> | <code>{type:&#39;error&#39;}</code>.</li><li><code>simWorker</code>: <code>{ type:&#39;run&#39;, inpText, targetDurationMs, files? }</code> → postea <code>{type:&#39;ready&#39;}</code> (una vez, tras compilar el wasm), <code>{type:&#39;log&#39;|&#39;err&#39;}</code>, <code>{type:&#39;done&#39;, rpt, outBuffer}</code> (ArrayBuffer transferible), <code>{type:&#39;error&#39;}</code>.</li><li><code>openSwmm2dWorker</code> / <code>gpu2dWorker</code>: <code>{ type:&#39;run2d&#39;, inp, triangleIds, meshFile|null, triangleVertices, dryDepth, wantVertexFields, frameIntervalMs }</code> (+ <code>wasmBinary</code> transferido opcional) → postea <code>{type:&#39;status2d&#39;, stage}</code>, <code>{type:&#39;stdout&#39;|&#39;stderr&#39;}</code>, <code>{type:&#39;progress2d&#39;, elapsedMs}</code>, <code>{type:&#39;results2d&#39;, triangleIds, frames, diagnostics, report}</code> (buffers transferidos), <code>{type:&#39;error&#39;}</code>.</li></ul><p><strong>Asimetría del ciclo de vida de los workers:</strong> el worker 1D se crea una vez y se reutiliza (<code>simWorker.onerror</code> lo anula para que la siguiente corrida lo recree); los workers 2D se recrean en cada corrida y una instancia WASM fallida no puede reutilizarse (<code>openSwmm2dWorker.js:376</code>).</p><p><strong>Detener:</strong> <code>stopSimulationWorker()</code> (<code>app.js:1038-1059</code>) termina ambos workers, limpia el timer de progreso falso y restaura el botón Run.</p><h2 id="ejecucion-1d-vs-2d-dentro-del-motor" tabindex="-1">Ejecución 1D vs 2D dentro del motor <a class="header-anchor" href="#ejecucion-1d-vs-2d-dentro-del-motor" aria-label="Permalink to &quot;Ejecución 1D vs 2D dentro del motor&quot;">​</a></h2><ul><li><strong><code>simWorker.js</code></strong> — runner 1D bloqueante: escribe un <code>.inp</code> en MEMFS, llama <code>stride(engine, 10_000_000, …)</code> una vez para correr hasta completarse, lee <code>/rpt.rpt</code> y <code>/out.out</code>, transfiere los bytes. Sin muestreo de cuadros (<code>simWorker.js:76-81</code>).</li><li><strong><code>openSwmm2dWorker.js</code></strong> — runner 1D+2D: mismo ciclo de vida pero avanza en bloques <code>stride(…, stepsPerYield=256)</code> y <strong>muestrea cuadros por triángulo en JS entre strides</strong> (<code>readFrame</code>, <code>openSwmm2dWorker.js:158-179</code>) — esto es lo que produce la línea de tiempo de la animación 2D. También lee los diagnósticos 2D (balance de masa, pasos del solver, velocidad máxima) y el reporte. Sin parseo de <code>.out</code> en esta vía.</li><li><strong><code>webgpu/gpu2dWorker.js</code></strong> — mismo contrato <code>results2d</code>, pero el avance 2D corre en el marcher de GPU (ver el subsistema de malla 2D y WebGPU) en lugar del solver WASM.</li></ul><h2 id="resultados" tabindex="-1">Resultados <a class="header-anchor" href="#resultados" aria-label="Permalink to &quot;Resultados&quot;">​</a></h2><p><strong>Parser binario <code>.out</code> — <code>swmmOutParser.js</code>:</strong> lee el footer del archivo de salida SWMM (últimos seis INT32: <code>idNamesOffset, objPropsOffset, resultsOffset, numPeriods, errCode, magicEnd</code>), valida el magic <code>516114522</code>, parsea los headers y los conteos de variables, y expone <strong>vistas <code>Float32Array</code> zero-copy</strong> sobre los registros de periodo (<code>readResults</code>, <code>swmmOutParser.js:132-180</code>). Caminos calientes: <code>getTimeSeries(type,index,varIndex)</code> (cacheado, <code>:184-209</code>) y <code>getStepData(type,step,varIndex)</code> para el coloreado del mapa por paso (<code>:212-230</code>).</p><p><strong>Presentación — <code>results.js</code>:</strong> el texto <code>.rpt</code> se parsea una vez en tablas resumen (<code>parseNodeDepths</code>, <code>parseLinkFlows</code>, <code>parseFlooding</code>, <code>parseNodeInflows</code>, <code>parseOutfallLoadings</code>, <code>parseConduitSurcharges</code>, <code>parseSubcatchmentRunoffs</code>, <code>parseContinuityErrors</code>, <code>parseEngineErrors</code>, <code>parseTimeSeries</code> — <code>results.js:59-366</code>). <code>ResultStyling</code> (<code>results.js:369-547</code>) es dueño del coloreado: <code>applyToMapForStep(step)</code> (<code>:402-518</code>) pinta primero los cuadros de la malla 2D, luego la vía binaria optimizada <code>.out</code>, y luego el fallback <code>.rpt</code>. <code>displayResults</code> (<code>:790-1288</code>) construye tarjetas KPI, chips de continuidad, leyendas de color, tablas de resultados ordenables/filtrables con minigráficos lazy vía <code>IntersectionObserver</code>, y fly-to al hacer clic. <code>display2DResults</code> (<code>:1291-1492</code>) colorea la malla por cuadro, expone un selector de tirante/carga/velocidad y maneja el mismo deslizador de tiempo vía una serie de tiempo sintética.</p><p><strong>Gráficos:</strong> <code>profile.js</code> <code>ProfilePlot.openForNodes</code> (<code>:630</code>) traza BFS por conductos, muestrea el terreno y dibuja un perfil hidráulico (código de color de capacidad: rojo ≥1.0 en carga, ámbar ≥0.85, cian normal). <code>plot.js</code> <code>TimeSeriesPlot</code> (<code>:227</code>) grafica series de tiempo multi-serie desde el binario <code>.out</code> (preferido) o con fallback <code>.rpt</code>.</p><h2 id="los-binarios-distribuidos" tabindex="-1">Los binarios distribuidos <a class="header-anchor" href="#los-binarios-distribuidos" aria-label="Permalink to &quot;Los binarios distribuidos&quot;">​</a></h2><p><code>public/</code> contiene <strong>dos builds idénticos del motor</strong> (misma fábrica, mismo tamaño 4.614.086 bytes, mismo sello):</p><ul><li><code>openswmm2d.js</code> + <code>openswmm2d.wasm</code> — usados por <code>openSwmm2dWorker.js</code>, <code>gpu2dWorker.js</code> y todos los <code>scripts/*.mjs</code>.</li><li><code>swmm6wasm.js</code> + <code>swmm6wasm.wasm</code> — una copia usada por <code>simWorker.js</code> (nombre legado).</li></ul><p>Ambos son pegamento Emscripten de 2 líneas que exporta la fábrica <strong><code>createOpenSwmm2D</code></strong> (<code>swmm6wasm.js:1-2</code>). Los archivos <code>.version.json</code> registran el commit/describe/fecha del motor (escritos por el script de build).</p><h2 id="instanciacion-de-modulo" tabindex="-1">Instanciación de módulo <a class="header-anchor" href="#instanciacion-de-modulo" aria-label="Permalink to &quot;Instanciación de módulo&quot;">​</a></h2><p>El wasm se <strong>compila una vez, se instancia por corrida</strong> (~10–50 ms por re-instanciación, según <code>simWorker.js:8-12</code>):</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// simWorker.js:19-63 (condensed)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WebAssembly.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">compileStreaming</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;swmm6wasm.wasm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// once</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> factory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createOpenSwmm2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ noInitialRun: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    instantiateWasm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">imports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">cb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WebAssembly.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">instantiate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, imports).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m.instance)) });</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> engine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> factory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// fresh instance each run</span></span></code></pre></div><p><code>wasm/openswmm2d_exports.cpp</code> es deliberadamente <strong>solo-fuente</strong> (6 líneas): incluye los headers públicos del motor y nada más, para que Emscripten exporte la API C como funciones de librería sin arrastrar el ciclo de vida de <code>main</code>.</p><h2 id="api-c-exportada-31-simbolos-en-exported-functions" tabindex="-1">API C exportada (31 símbolos en <code>EXPORTED_FUNCTIONS</code>) <a class="header-anchor" href="#api-c-exportada-31-simbolos-en-exported-functions" aria-label="Permalink to &quot;API C exportada (31 símbolos en `EXPORTED_FUNCTIONS`)&quot;">​</a></h2><p><strong>Ciclo de vida</strong> (<code>swmm_engine_*</code>; máquina de estados <code>CREATED → OPENED → INITIALIZED → STARTED → [RUNNING] → ENDED → CLOSED</code> según <code>openswmm_engine.h:31-37</code>):</p><table tabindex="0"><thead><tr><th>Símbolo</th><th>Significado</th></tr></thead><tbody><tr><td><code>swmm_engine_create</code> / <code>destroy</code></td><td>Asignar / liberar el handle del motor</td></tr><tr><td><code>swmm_engine_open(engine, inp, rpt, out, plugin)</code></td><td>Parsear el <code>.inp</code> (+ librería plugin opcional, siempre <code>0</code> en wasm)</td></tr><tr><td><code>swmm_engine_initialize</code> / <code>start</code> / <code>end</code> / <code>close</code></td><td>Transiciones del ciclo de vida (<code>start</code> toma <code>save_results</code>)</td></tr><tr><td><code>swmm_engine_step(engine, double* elapsed)</code></td><td>Avanzar exactamente un paso de tránsito</td></tr><tr><td><code>swmm_engine_stride(engine, n_steps, double* elapsed)</code></td><td>Avanzar hasta <code>n</code> pasos en una llamada</td></tr><tr><td><code>swmm_engine_report(engine)</code></td><td>Escribir el archivo de reporte resumen</td></tr></tbody></table><p><strong>Accesores 2D</strong> (<code>swmm_2d_*</code>): <code>swmm_2d_triangle_count</code>, <code>swmm_2d_get_depths_bulk</code>, <code>swmm_2d_get_heads_bulk</code>, <code>swmm_2d_get_stat_max_velocities</code>, <code>swmm_2d_get_continuity_error</code>, <code>swmm_2d_get_solver_steps</code> (+ legado <code>swmm_2d_get_cvode_steps</code>), <code>swmm_2d_get_mass_balance</code> (10 términos double), y accesores opcionales de vértices/bordes (<code>swmm_2d_vertex_count</code>, <code>swmm_2d_vertex_get_xyz_bulk</code>, <code>swmm_2d_edge_get_geometry_bulk</code>, <code>swmm_2d_get_edge_flux_bulk</code>, <code>swmm_2d_vertex_get_render_depths_bulk</code>, <code>swmm_2d_vertex_get_heads_bulk</code>).</p><p><strong>Acceso/control de nodos 1D</strong> (<code>swmm_node_*</code>): <code>swmm_node_count</code>, <code>swmm_node_get_heads/depths/volumes_bulk</code>, <code>swmm_node_set_lateral_inflow</code>, <code>swmm_node_set_pond_area</code> — usados por el split de WebGPU para devolver el intercambio 1D↔2D al motor.</p><p>Más <code>malloc</code>/<code>free</code> para la gestión de memoria JS↔wasm.</p><h2 id="capa-de-wrapper-js-—-openswmm2dworker-js" tabindex="-1">Capa de wrapper JS — <code>openSwmm2dWorker.js</code> <a class="header-anchor" href="#capa-de-wrapper-js-—-openswmm2dworker-js" aria-label="Permalink to &quot;Capa de wrapper JS — `openSwmm2dWorker.js`&quot;">​</a></h2><ul><li><code>bindApi(Module)</code> (<code>:79-107</code>) envuelve cada símbolo con <code>Module.cwrap</code>; <code>optional()</code> retorna <code>null</code> para símbolos ausentes de un build, de modo que un worker maneja múltiples configuraciones de motor.</li><li><code>check(code, op, Module, reportPath, payload)</code> (<code>:109-148</code>) lanza errores ricos; ante un fallo, vuelca el <code>.rpt</code> (líneas de error filtradas o los últimos 1500 caracteres) y los primeros 3000 caracteres del INP como mensajes <code>stderr</code> — esta es tu primera parada cuando una simulación &quot;falla en silencio&quot;.</li><li><code>readFrame(Module, api, engine, count, elapsedMs)</code> (<code>:158-179</code>) mallocs arrays de tirante/carga/velocidad, los lee en bulk, retorna Float64Arrays, libera en <code>finally</code>.</li><li><code>readVelocity(...)</code> (<code>:196-229</code>) reconstruye la <strong>velocidad física centrada en la celda</strong> a partir del flujo de borde + la geometría de borde vía una solución de mínimos cuadrados de <code>(NᵀN)v = Nᵀq</code> (q = flujo/longitud), convirtiendo el caudal específico en velocidad (<code>/h</code>); las celdas secas (<code>h ≤ dryDepth</code>) se ponen en cero.</li><li><code>readDiagnostics(...)</code> (<code>:231-257</code>) lee el balance de masa, los pasos internos del solver y las estadísticas de velocidad máxima.</li><li><code>run(payload)</code> (<code>:259-368</code>) es el bucle de corrida 2D: escribir <code>/model2d.inp</code> (+ archivo de malla opcional) → ciclo de vida <code>open→initialize→start</code> con <code>check()</code> tras cada uno → <code>do/while</code> <code>stride(engine, 256, …)</code> muestreando cuadros a <code>frameIntervalMs</code> → cuadro final + diagnósticos → <code>end→report</code> → postear <code>results2d</code>.</li></ul><h2 id="gestion-de-memoria" tabindex="-1">Gestión de memoria <a class="header-anchor" href="#gestion-de-memoria" aria-label="Permalink to &quot;Gestión de memoria&quot;">​</a></h2><ul><li>Todos los punteros vienen de <code>Module._malloc(bytes)</code> y se liberan con <code>Module._free(ptr)</code>; las lecturas escalares usan <code>Module.getValue(ptr, &#39;double&#39;|&#39;i32&#39;)</code>; el código nunca toca vistas HEAP crudas directamente.</li><li>Los archivos van al sistema de archivos virtual MEMFS de Emscripten: <code>FS.writeFile(&#39;/in.inp&#39;, inpText)</code>, <code>FS.readFile(&#39;/rpt.rpt&#39;, {encoding:&#39;utf8&#39;})</code>, <code>FS.readFile(&#39;/out.out&#39;)</code> que retorna un <code>Uint8Array</code> <strong>vista sobre el heap del wasm</strong>. El worker recorta una copia (<code>outBytes.buffer.slice(...)</code>, <code>simWorker.js:162</code>) para que el buffer del heap pueda desprenderse en la transferencia.</li><li>El worker 2D desvincula sus archivos temporales en <code>finally</code> (<code>openSwmm2dWorker.js:364-366</code>).</li></ul>',40)])])}const k=o(r,[["render",t]]);export{h as __pageData,k as default};
